N=json.loads((R/'candidatos-vivos.json').read_text());T={t['key']:t for t in json.loads((R/'alvos-planejados.json').read_text())}
rows=[]
def c(key,src,target,text,extra,img,cod='A-aula',origin='AnKing',**kw):
 rows.append(dict(key=key,src=src,target=target,text=text,extra=extra,img=img,cod=cod,origin=origin,**kw))
def s(nid,target,extra,img,cod='A-aula',text=None):
 rows.append(dict(key='sh-'+str(nid),nid=nid,target=target,extra=extra,img=img,cod=cod,**({'text':text} if text else {})))
c('transducao',1792624810878,'receptor','A conversão de <b>estímulos sensoriais</b> em sinais elétricos chama-se {{c1::transdução}}.','Receptors convert stimulus energy into a change in membrane potential. Sensory neurons then carry the information toward integrating circuits.','neuronio',origin='Kenhub')
c('circuito-funcional',1792624810931,'circuito','<div data-nebli-organizacao="true"><b>Arco reflexo</b>, do estímulo à resposta:<br>Entrada no centro: via {{c1::aferente}}<br>Saída do centro: via {{c1::eferente}}</div>','Receptors detect a stimulus, central circuits integrate the input, and efferent neurons activate an effector. Interneurons can link sensory input to motor output.','funcional',origin='Kenhub',organizador=True)
c('inducao-neural',1479351739996,'neurulacao','Na <b>neurulação</b>, a {{c2::notocorda}} induz o ectoderma sobrejacente a formar a {{c1::placa neural}}.','Induction converts surface ectoderm into neuroectoderm. The neural plate folds before the neural tube separates from the surface.','neurulacao')
c('fechamento-tubo',1479351745905,'neurulacao','Na <b>neurulação</b>, as {{c2::pregas neurais}} fundem-se na linha mediana para formar o {{c1::tubo neural}}.','Closure encloses a lumen while the surrounding surface ectoderm separates. The tube develops into the brain and spinal cord.','neurulacao')
c('origem-central-periferica',1717015075616,'neurulacao','No <b>desenvolvimento nervoso</b>, a crista neural origina componentes do sistema {{c1::periférico}}, e o tubo neural, do {{c1::central}}.','Neural crest cells migrate away from the closing tube. CNS neurons and macroglia arise from neuroectoderm; microglia have a different embryonic origin.','neurulacao',origin='AnKing-MCAT',contraste_complementar=True)
c('prosencefalo',1479351788638,'vesiculas','No <b>desenvolvimento encefálico</b>, o {{c3::prosencéfalo}} origina o {{c1::telencéfalo}} e o {{c2::diencéfalo}}.','Expansion of the telencephalic vesicles forms the cerebral hemispheres. The diencephalon remains around the third ventricle.','vesiculas')
c('mesencefalo-origem',1479351815852,'vesiculas','No <b>desenvolvimento encefálico</b>, a vesícula {{c2::média}} mantém-se como {{c1::mesencéfalo}}.','Unlike the forebrain and hindbrain, the midbrain does not split into two secondary vesicles. Its narrow cavity becomes the cerebral aqueduct.','vesiculas')
c('rombencefalo',1479351830944,'vesiculas','No <b>desenvolvimento encefálico</b>, o {{c3::rombencéfalo}} origina {{c1::metencéfalo}} e {{c2::mielencéfalo}}.','The two hindbrain divisions form different adult structures. The metencephalon gives rise to pons and cerebellum, while the myelencephalon forms the medulla.','vesiculas')
c('metencefalo-adulto',1479351836035,'metencefalo','O <b>metencéfalo embrionário</b> origina a {{c1::ponte}} e o {{c1::cerebelo}} no adulto.','A common embryonic origin explains why both structures belong to the hindbrain, although they have different adult shapes and connections.','vesiculas')
c('mielencefalo-adulto',1479351844708,'metencefalo','O <b>mielencéfalo embrionário</b> origina o {{c1::bulbo}} no adulto.','The medulla is the caudal part of the brainstem and continues into the spinal cord. It develops below the pontine region.','vesiculas')
c('dendritos',1479430330034,'neuronio','Os prolongamentos especializados em <b>receber sinais</b> de outros neurônios são os {{c1::dendritos}}.','Branching expands the receptive surface. Synaptic inputs on dendrites and soma influence whether the neuron generates an action potential.','neuronio')
c('soma',1479430341680,'soma','O <b>centro metabólico</b> do neurônio, com núcleo e organelas de síntese, é o {{c1::corpo celular}}.','The soma synthesizes proteins required by the neuron. Axonal transport distributes materials to distant portions of its processes.','neuronio')
c('axonio',1479430346525,'neuronio','O prolongamento especializado em <b>conduzir a saída</b> do neurônio para outras células é o {{c1::axônio}}.','Action potentials travel along the axon to terminal regions, where communication with another neuron or an effector occurs.','neuronio')
c('cicatriz-glial',1479430487028,'astrocito','Após <b>lesão nervosa</b>, {{c2::astrócitos}} participam da formação de {{c1::cicatriz glial}}.','Reactive astrocytes change their processes and help contain damaged tissue. This response does not replace lost neurons with functionally equivalent neurons.','glia')
c('potassio-glia',1479430452218,'astrocito','A <b>homeostase extracelular</b> depende da captação de {{c2::potássio}} por {{c1::astrócitos}}.','Extracellular potassium rises during neuronal activity. Buffering limits disturbances in membrane excitability and supports continued signaling.','glia')
c('recaptacao-glia',1479430475147,'astrocito','A glia que remove o <b>excesso de neurotransmissores</b> ao redor das sinapses é o {{c1::astrócito}}.','Uptake helps terminate signaling and controls extracellular glutamate. This prevents sustained receptor activation and excitotoxic stress.','glia')
c('oligodendrocito',1479430425469,'mielinizadores','{{c2::Oligodendrócitos}} formam a <b>bainha de mielina</b> no sistema nervoso {{c1::central}}.','Oligodendrocyte processes wrap CNS axons. Myelin insulates internodes and supports rapid saltatory conduction.','glia')
c('oligodendrocito-varios',1479430428553,'mielinizadores','Um <b>oligodendrócito</b> pode mielinizar segmentos de {{c1::vários axônios}}.','Separate processes from one oligodendrocyte can form internodes on different CNS axons. A myelinating Schwann cell instead forms one internode on one axon.','glia')
c('schwann',1479430497815,'mielinizadores','{{c2::Células de Schwann}} formam a <b>bainha de mielina</b> no sistema nervoso {{c1::periférico}}.','Myelinating Schwann cells wrap peripheral axons. Their internodes alternate with nodes of Ranvier, where action potentials regenerate.','mielina')
c('schwann-segmento',1479430500748,'mielinizadores','Uma <b>célula de Schwann mielinizante</b> forma {{c1::um internódulo}} de um único axônio.','A long myelinated peripheral axon requires many Schwann cells in series. Nonmyelinating Schwann cells can ensheath multiple small axons without forming myelin.','mielina')
# Cópia de idioma dedicada: a nota NEBLI existente deste AnKing está na UC03 e deve continuar em inglês.
c('microglia',1479430563185,'microglia','A <b>glia fagocitária</b> residente no sistema nervoso central é a {{c1::micróglia}}.','Microglia clear debris and respond to tissue injury. Resident microglia arise from embryonic yolk sac macrophage precursors, rather than requiring continuous replacement by blood monocytes.','glia',copia_traducao_uc07='Cópia existenteUC03 em inglês; preservar sua nota,estudo e comentário e produzir versão portuguesa UC07 independente.')
c('guillain-barre',1483844967260,'mielina-clinica','Na forma <b>desmielinizante de Guillain–Barré</b>, a mielina afetada é produzida por {{c1::células de Schwann}}.','This is a peripheral demyelinating process, in contrast to central demyelination in multiple sclerosis. Axonal variants of Guillain–Barré syndrome also exist.','mielina','A-step')
# O AnKing de EM já foi incorporado à UC03; compartilhar sem alterar sua redação inglesa seria incompatível com o novo idioma.
c('esclerose-multipla',1481836336120,'mielina-clinica','A <b>esclerose múltipla</b> envolve destruição {{c2::autoimune}} da mielina central e lesão de {{c1::oligodendrócitos}}.','Loss of CNS myelin slows or blocks conduction. The affected region determines the deficit; this contrasts with peripheral demyelination.','glia','A-step',copia_traducao_uc07='Preservar cópia inglesaUC03 e seus dois clozes; versão de idioma dedicada paraUC07.')
c('astrocitos-capilares',1479430617535,'astrocito','Os astrócitos relacionam-se com os <b>capilares da barreira hematoencefálica</b> por {{c1::prolongamentos podais}}.','Astrocytic endfeet surround CNS microvessels and support barrier function. Endothelial tight junctions provide the principal physical seal; astrocytes regulate its maintenance rather than forming that seal themselves.','glia')
c('sinapse-quimica',1555042817794,'sinapses','Na <b>sinapse</b> {{c1::química}}, a comunicação entre células depende de {{c2::neurotransmissores}}.','The transmitter crosses an extracellular cleft and binds postsynaptic receptors. The response can increase or decrease the likelihood of firing.','sinapse',origin='AnKing-MCAT')
c('sinapse-eletrica',1555081720829,'sinapses','Na <b>sinapse</b> {{c2::elétrica}}, as células comunicam-se diretamente por {{c1::junções comunicantes}}.','Gap junction channels allow ionic current to pass between cells. Direct coupling supports rapid transmission and synchronization.','sinapse',origin='AnKing-MCAT')
c('liberacao-sinaptica',1555041373126,'liberacao','Na <b>sinapse química</b>, o {{c3::potencial de ação}} abre {{c4::canais de cálcio}} no terminal {{c2::pré-sináptico}}, liberando {{c1::neurotransmissores}}.','Calcium entry triggers vesicle fusion. Released transmitter binds postsynaptic receptors; the resulting potential is not necessarily sufficient to trigger another action potential.','sinapse',origin='AnKing-MCAT')
c('saltatoria',1479430507738,'saltatoria','Em <b>axônios mielinizados</b>, os nós de {{c2::Ranvier}} permitem condução {{c1::saltatória}}.','Myelin limits current loss between nodes. Action potentials regenerate at the nodes rather than continuously along every internodal segment.','mielina')
c('canais-nodais',1479430512463,'saltatoria','Os <b>nós de Ranvier</b> concentram canais de {{c1::sódio}} dependentes de voltagem.','High channel density permits rapid regeneration of the action potential. Insulated internodes carry local current to the next node.','mielina')
c('fibras-propriocepcao',1479515764414,'fibras-sensoriais','A <b>propriocepção muscular</b> é conduzida por fibras do grupo {{c1::I}}, equivalentes às Aα.','Group I fibers include Ia and Ib afferents. Their large diameter and heavy myelination support rapid feedback about muscle length and tension.','fibras')
c('fibras-tato',1479515790990,'fibras-sensoriais','As fibras do <b>grupo II</b> associadas ao tato correspondem às fibras {{c1::Aβ}}.','These myelinated afferents conduct mechanosensory information rapidly. Their diameter is smaller than that of the largest group I afferents.','fibras')
c('fibras-dor-frio',1479515805801,'fibras-sensoriais','A <b>dor aguda e o frio</b> são conduzidos por fibras {{c1::III e Aδ}}.','Group III and Aδ are two names for thinly myelinated sensory fibers. Their conduction is slower than that of the larger group I and II fibers.','fibras')
c('fibras-dor-calor',1479515828250,'fibras-sensoriais','A <b>dor surda e o calor</b> são conduzidos por fibras {{c1::IV e C}}.','Group IV and C refer to small unmyelinated sensory axons. Their slow conduction contrasts with the thinly myelinated Aδ fibers that carry fast sharp pain.','fibras')
c('duas-dores',1609187258449,'primeira-dor','A <b>dor rápida</b> segue por fibras {{c1::Aδ}}, enquanto a <b>dor lenta</b> segue por {{c1::C}}.','Aδ fibers are thinly myelinated, whereas C fibers lack myelin. Their different conduction velocities help explain the two temporal components of nociception.','fibras',origin='Ankisthesia',contraste_complementar=True)
c('fibras-c',1484099198611,'velocidade','As fibras nervosas <b>mais finas e amielínicas</b> pertencem ao grupo {{c1::C}}.','Small diameter raises axial resistance, and absent myelin prevents saltatory conduction. These features account for slow conduction compared with myelinated fibers.','fibras')
s(1792697134942,'pseudounipolar','Both branches are axonal processes. The soma lies off the main path, allowing sensory signals to pass from the peripheral branch into the central branch.','morfologias',text='O <b>neurônio sensitivo</b> do gânglio espinal é {{c1::pseudounipolar}}: seu ramo {{c2::periférico}} vem do receptor, e o {{c3::central}} entra na medula.')
s(1792588686960,'snc-snp','The CNS comprises brain and spinal cord. Peripheral nerves, ganglia and sensory or motor endings connect these central structures with the body.','divisoes')
s(1792588686968,'encefalo','These divisions have different cellular architectures and connections. The cerebral hemispheres belong to the cerebrum, while the brainstem continues into the spinal cord.','encefalo')
s(1792588686971,'encefalo','The midbrain lies above the pons, which lies above the medulla. The cerebellum attaches dorsally and is not a fourth part of the brainstem.','encefalo')
s(1792329944339,'somatico-visceral','Somatic motor output reaches skeletal muscle. Visceral motor output instead targets smooth muscle, cardiac muscle and glands.','funcional',text='Os nervos <b>motores somáticos</b> inervam {{c1::músculo esquelético}}.')
s(1792588686967,'autonomo','The autonomic pathway uses a peripheral ganglionic relay. Visceral sensory afferents carry information inward and are distinct from this motor output.','funcional',text='<div data-nebli-organizacao="true"><b>Via eferente visceral</b>:<br>Pré-ganglionar: corpo no {{c1::sistema nervoso central}}<br>Sinapse no {{c1::gânglio autônomo}}<br>Pós-ganglionar: alcança o {{c1::órgão efetor}}</div>')
s(1792329941889,'pares-nervos','The spinal pairs comprise 8 cervical, 12 thoracic, 5 lumbar, 5 sacral and 1 coccygeal pair. Cranial nerves are counted separately.','divisoes',text='Há {{c1::31}} pares de <b>nervos espinais</b> no total.')
s(1792588686964,'raizes','The dorsal root carries sensory input and bears the sensory ganglion. The ventral root carries motor output; their union forms a mixed spinal nerve.','raizes')
s(1792265021996,'ganglio','Sensory neuron somata remain outside the spinal cord. Their central processes enter through the dorsal root and carry peripheral information into the CNS.','raizes',text='Os <b>corpos dos neurônios sensitivos primários</b> ficam nos {{c1::gânglios espinais}}.')
c('ramos-mistos',1479515714285,'ramos','Os <b>ramos posteriores</b> dos nervos espinais contêm fibras {{c1::aferentes e eferentes}}.','Ventral rami are also mixed. Roots separate sensory input from motor output before they unite; rami distribute the already mixed spinal nerve.','raizes')
s(1792697128629,'ramos','Most thoracic ventral rami continue as intercostal nerves. Plexuses redistribute fibers among named peripheral nerves; dorsal rami do not form these limb plexuses.','raizes')
c('branca-composicao',1555109212272,'cinzenta-branca','A <b>substância</b> {{c1::branca}} contém predominantemente {{c2::axônios mielinizados}}.','Lipid-rich myelin gives this tissue its pale appearance. Axonal bundles link gray matter regions within the CNS.','cinzenta',origin='AnKing-MCAT')
c('cinzenta-composicao',1555109453749,'cinzenta-branca','A <b>substância</b> {{c1::cinzenta}} concentra {{c2::corpos celulares}} e dendritos.','Gray matter contains neuronal somata, dendrites, synapses, glia and axons. It forms superficial cortex and deep nuclei, rather than being limited to the brain surface.','cinzenta',origin='AnKing-MCAT')
s(1792329455442,'medula-cinzenta','The central gray matter contains local circuits and motor neuron somata. Peripheral white matter carries ascending and descending axons.','medula',text='Na <b>medula espinal</b>, a substância {{c1::cinzenta}} fica no centro.')
s(1792329455695,'medula-cinzenta','The surrounding white matter is organized into columns containing tracts. This arrangement differs from the superficial gray cortex of the cerebrum and cerebellum.','medula',text='Na <b>medula espinal</b>, a substância {{c1::branca}} fica na periferia.')
s(1792329761664,'branca-rostral','More rostral levels contain more ascending axons collected from below and descending axons headed to lower levels. Consequently, the relative amount of white matter increases rostrally.','niveis')
s(1792329455992,'corno-ventral','These lower motor neurons send axons through ventral roots toward skeletal muscle. Dorsal gray matter instead receives and processes sensory input.','medula',text='O <b>corno</b> {{c1::anterior}} da medula contém os corpos dos motoneurônios somáticos.')
c('distais-laterais',1479515890214,'somatotopia','No <b>corno anterior</b>, motoneurônios para músculos {{c2::distais}} ficam mais {{c1::lateralmente}}.','Medial motor pools supply axial and proximal muscles. This mediolateral organization links the location of motor neuron groups to the body region they control.','somatotopia')
c('extensores-ventrais',1479515877298,'flexores','No <b>corno anterior</b>, motoneurônios para {{c2::extensores}} ficam mais {{c1::ventralmente}}.','Flexor motor pools lie more dorsally within the anterior horn. Both groups are motor; this is not the sensory dorsal horn versus motor ventral horn distinction.','somatotopia')
c('flexores-dorsais',1479515872878,'flexores','No <b>corno anterior</b>, motoneurônios para {{c2::flexores}} ficam mais {{c1::dorsalmente}}.','This dorsoventral pattern is internal to the motor anterior horn. It complements the medial axial versus lateral distal organization.','somatotopia')
s(1792329760618,'corticoespinal','Most corticospinal fibers cross in the caudal medulla. Above that crossing a unilateral lesion affects the opposite side; below it, the lateral tract affects the same side.','lesao',text='O trato <b>{{c1::corticoespinal}}</b>, no encéfalo, participa do movimento voluntário dos membros {{c2::contralaterais}}.')
c('broca-fala',1481514003114,'broca','A <b>afasia de Broca</b> caracteriza-se por fala {{c1::não fluente}}.','A lesion of the dominant inferior frontal language region can impair speech production. The historical case illustrates anatomical localization within a larger language network.','broca','A-aula')
c('transporte-axonal',1479430581908,'tracadores','O <b>transporte axonal</b> utiliza {{c1::microtúbulos}} como trilhos intracelulares.','Motor proteins carry cargo along the axon. Anterograde transport proceeds toward terminals, whereas retrograde transport returns toward the soma.','neuronio')
c('ressonancia-funcional',1561068151394,'imagem-funcional','A {{c1::ressonância magnética funcional}} detecta alterações {{c2::hemodinâmicas}} associadas à <b>atividade cerebral</b>.','Task-related activation is inferred from changes linked to blood oxygenation. It complements structural anatomy and does not directly record neuronal action potentials or prove causation.','funcional-imagem',origin='AnKing-MCAT')
# Reconhecimento dos níveis: imagem original AnKing; a resposta fica focal e os critérios no Extra.
c('corte-mesencefalo',1480873977898,'tronco-seccoes','Qual nível do <b>tronco encefálico</b> está no corte? {{c1::Mesencéfalo rostral}}','The cerebral aqueduct, tectal colliculi and cerebral peduncles identify the midbrain. The image is shown without the answer labels on the front.','cortes',front_image='2f7dffad3cdf444b07dad638e1ab84f5.png',back_image='51ffc21fce0d7336a611bd0aa447e75c.png')
c('corte-ponte',1480874931616,'tronco-seccoes','Qual nível do <b>tronco encefálico</b> está no corte? {{c1::Ponte rostral}}','The expanded ventral basis and dorsal fourth ventricle identify the pons. Transverse pontine fibers contribute to the large ventral profile.','cortes',front_image='abb5292e3001154856ff302fd719582b.png',back_image='46d2eda4c1787ca17b5b1fb3f029661d.png')
c('corte-bulbo',1480875089335,'tronco-seccoes','Qual nível do <b>tronco encefálico</b> está no corte? {{c1::Bulbo aberto}}','An open fourth ventricle and prominent inferior olivary nuclei distinguish this rostral medullary section. The closed caudal medulla instead surrounds a central canal.','cortes',front_image='21442b297d46e09ed11cc5598c8a3f8a.png',back_image='105e157ff2a5508373ddee8c74487630.webp')
s(1792588686961,'autonomo','Sympathetic and parasympathetic outputs control visceral effectors. Enteric circuits in the gut wall also integrate locally and interact with both divisions.','funcional',text='<div data-nebli-organizacao="true"><b>Organização autônoma</b>, incluindo circuitos locais:<br>{{c1::Simpático}}<br>{{c1::Parassimpático}}<br>{{c1::Entérico}}</div>')
c('pares-cranianos',1540251909132,'pares-nervos','Há {{c1::12}} pares de <b>nervos cranianos</b>.','Cranial nerves connect with the brain,while spinal nerves connect with the spinal cord. The two counts refer to different anatomical groups.','divisoes',origin='AnatoKing')
c('interneuronios',1554954906033,'circuito','Em <b>arcos reflexos</b>, {{c1::interneurônios}} conectam vias sensitivas a {{c2::motoneurônios}}.','Interneurons integrate sensory input and influence motor output. Polysynaptic reflexes include such a relay,whereas a monosynaptic sensory-to-motor connection does not require an interneuron.','funcional',origin='AnKing-MCAT',back_image='755339a3d01c11c1d48372dfa571e5f2.jpg')
