c('intumescencia-cervical',1549136300119,'intumescencias','A dilatação medular ligada à <b>inervação dos membros superiores</b> é a {{c1::intumescência cervical}}.','Upper limb innervation requires larger populations of motor neurons and local sensory circuits. The enlargement corresponds to the roots supplying the brachial plexus.','niveis',origin='AnatoKing')
c('intumescencia-lombossacral',1549136367353,'intumescencias','A dilatação medular ligada à <b>inervação dos membros inferiores</b> é a {{c1::intumescência lombossacral}}.','Lower limb innervation requires larger populations of motor neurons and local sensory circuits. The enlargement corresponds to roots supplying the lumbosacral plexus; its function differs from the cervical enlargement.','niveis',origin='AnatoKing')
